  {
    "term": "Partition of Sample Space",
    "definition": "A collection of non-empty, pairwise disjoint events {E₁, ..., Eₙ} whose union equals the sample space S."
  },
  {
    "term": "Bayes' Theorem",
    "definition": "A mathematical rule that calculates posterior probability of an event given prior probabilities and conditional likelihoods."
  },
  {
    "term": "Random Variable",
    "definition": "A real-valued function defined over the sample space of a random experiment."
  },
  {
    "term": "Bernoulli Trials",
    "definition": "Independent trials of a random experiment where each trial has exactly two mutually exclusive outcomes: success or failure."
  }
